import requests

BASE_URL = "http://localhost:8096"
TIMEOUT = 30

def test_post_api_v1_invoices_suggest_items():
    url = f"{BASE_URL}/api/v1/invoices/suggest-items"
    params = {"dry_run": "true"}
    payload = {
        "client_name": "Test Client",
        "first_item": "Consulting Services"
    }
    headers = {
        "Content-Type": "application/json"
    }

    try:
        response = requests.post(url, params=params, json=payload, headers=headers, timeout=TIMEOUT)
        assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"
        json_response = response.json()
        assert isinstance(json_response, list), "Response should be a list"
        # Each item should be a dict representing an InvoiceItem (not empty)
        for item in json_response:
            assert isinstance(item, dict), "Each suggested item should be a dict"
            # Basic checks for expected keys, depending on typical invoice item structure
            assert "description" in item or "name" in item or len(item) > 0, "Suggested item should contain details"
    except requests.RequestException as exc:
        assert False, f"Request failed: {exc}"

test_post_api_v1_invoices_suggest_items()

import requests

BASE_URL = "http://localhost:8096"
TIMEOUT = 30

def test_get_api_v1_invoices_list_all_invoices():
    url = f"{BASE_URL}/api/v1/invoices"
    try:
        response = requests.get(url, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request failed: {e}"
    assert response.status_code == 200, f"Expected status 200, got {response.status_code}"

    try:
        invoices = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    assert isinstance(invoices, list), f"Expected response to be a list, got {type(invoices)}"
    # Optionally, check that each item has expected keys for an InvoiceResponse
    if invoices:
        sample = invoices[0]
        assert isinstance(sample, dict), "Each invoice must be a dictionary"
        # Check for some expected keys based on schema in PRD: id, client_name, due_date, total, subtotal
        for key in ("id", "client_name", "due_date"):
            assert key in sample, f"Expected key '{key}' in invoice response"

test_get_api_v1_invoices_list_all_invoices()
